.share-link-row input:disabled { opacity: .55; }
.view-share-dialog .share-primary { padding-inline: 14px; background: var(--site-text-primary, #333); color: var(--site-bg, #fff); white-space: nowrap; }
.share-copy { display: flex; align-items: center; justify-content: center; gap: 7px; min-width: 112px; }
.share-copy svg { width: 16px; height: 16px; }
